                <Button isDisabled={isSaving} variant="tertiary" onPress={handleCancel}>
                  キャンセル
                </Button>
                <Button isDisabled={isSaving} type="submit" variant="primary">
                  {isSaving ? <Spinner size="sm" /> : null}
                  {isSaving ? "保存中" : "保存する"}
                </Button>
              </Drawer.Footer>
            </Form>
          </Drawer.Dialog>
        </Drawer.Content>
      </Drawer.Backdrop>
    </Drawer>
  );
}
