let createdCustomerCount = 0;

export function createCustomer(
  input: CreateCustomerInput,
  options: { simulateFailure?: boolean } = {},
): CreateCustomerResult {
  if (options.simulateFailure) {
    return { ok: false, reason: "顧客の追加に失敗しました。時間をおいて再試行してください。" };
  }
  const companyName = input.companyName.trim();
  if (companyName.length === 0) {
    return { ok: false, reason: "会社名を入力してください。" };
  }

  createdCustomerCount += 1;
  const record: CustomerRecord = {
    id: `customer_created_${createdCustomerCount}`,
    companyName,
    contactName: input.contactName.trim(),
    email: input.email.trim(),
    phone: input.phone?.trim() ?? "",
    status: input.status,
    lastContactedAt: "2026-09-05",
    note: input.note?.trim() ?? "",
  };
  customerRecords.push(record);

  return {
    ok: true,
    customer: {
      id: record.id,
      companyName: record.companyName,
      contactName: record.contactName,
      email: record.email,
      phone: record.phone,
      status: record.status,
