    companyName: customer.companyName,
    contactName: customer.contactName,
    email: customer.email,
    phone: customer.phone,
    status: customer.status,
    note: customer.note,
  };
}

export type CreateCustomerInput = {
  companyName: string;
  contactName: string;
  email: string;
  status: CustomerStatus;
  phone?: string;
  note?: string;
};

export type CreateCustomerResult =
  | { ok: true; customer: CustomerDetail }
  | { ok: false; reason: string };

let createdCustomerCount = 0;

export function createCustomer(
  input: CreateCustomerInput,
  options: { simulateFailure?: boolean } = {},
): CreateCustomerResult {
  if (options.simulateFailure) {
    return { ok: false, reason: "顧客の追加に失敗しました。時間をおいて再試行してください。" };
  }
  const companyName = input.companyName.trim();
  if (companyName.length === 0) {
    return { ok: false, reason: "会社名を入力してください。" };
  }

  createdCustomerCount += 1;
  const record: CustomerRecord = {
    id: `customer_created_${createdCustomerCount}`,
    companyName,
    contactName: input.contactName.trim(),
    email: input.email.trim(),
    phone: input.phone?.trim() ?? "",
    status: input.status,
    lastContactedAt: "2026-09-05",
    note: input.note?.trim() ?? "",
  };
  customerRecords.push(record);

  return {
    ok: true,
    customer: {
      id: record.id,
      companyName: record.companyName,
      contactName: record.contactName,
      email: record.email,
      phone: record.phone,
      status: record.status,
      note: record.note,
    },
  };
}

export type UpdateCustomerInput = {
  companyName: string;
  contactName: string;
  email: string;
  status: CustomerStatus;
};

export type UpdateCustomerResult =
  | { ok: true; customer: CustomerDetail }
  | { ok: false; reason: string };

export function updateCustomer(
  customerId: string,
  input: UpdateCustomerInput,
  options: { simulateFailure?: boolean } = {},
): UpdateCustomerResult {
  if (options.simulateFailure) {
    return { ok: false, reason: "変更の保存に失敗しました。時間をおいて再試行してください。" };
  }
  const companyName = input.companyName.trim();
  if (companyName.length === 0) {
    return { ok: false, reason: "会社名を入力してください。" };
  }
  const record = customerRecords.find(({ id }) => id === customerId);
  if (!record) {
    return { ok: false, reason: "対象の顧客が見つかりません。" };
  }

  record.companyName = companyName;
  record.contactName = input.contactName.trim();
  record.email = input.email.trim();
  record.status = input.status;

  return {
    ok: true,
    customer: {
      id: record.id,
      companyName: record.companyName,
      contactName: record.contactName,
      email: record.email,
      phone: record.phone,
      status: record.status,
      note: record.note,
    },
  };
}

export type DeleteCustomerResult = { ok: true } | { ok: false; reason: string };

export function deleteCustomer(
  customerId: string,
  options: { simulateFailure?: boolean } = {},
): DeleteCustomerResult {
  if (options.simulateFailure) {
    return { ok: false, reason: "削除に失敗しました。時間をおいて再試行してください。" };
  }

