    expect(
      screen.getByText("メールアドレスは name@example.com の形式で入力してください。"),
    ).toBeInTheDocument();
    expect(screen.getByLabelText("メールアドレス")).toHaveValue("hanako.yamada");
    expect(listCustomerSummaries()).toHaveLength(4);
  });
});

describe("customer detail", () => {
